<template>
<section class="cobros"><header><h1>Caja y Cobros · Etapa 1</h1><p>Registra pagos de ventas confirmadas. No modifica el inventario.</p></header>
<div v-if="error" class="alerta">{{error}}</div><div v-if="exito" class="exito">{{exito}}</div>
<div class="panel"><h2>Consultar venta</h2><div class="fila"><label>Número de venta <input v-model.number="idVenta" type="number" min="1" placeholder="Ej. 1" @keyup.enter="consultar"></label><button @click="consultar" :disabled="cargando">{{cargando?'Consultando...':'Consultar saldo'}}</button></div></div>
<div v-if="resumen" class="panel"><h2>Venta #{{resumen.venta.id_venta}}</h2><p><strong>Stand:</strong> {{resumen.venta.ubicacion?.evento?.nombre}} · {{resumen.venta.ubicacion?.nombre}} | <strong>Estado:</strong> {{resumen.venta.estado}}</p>
<div class="metricas"><div><span>Total</span><strong>Bs {{resumen.total}}</strong></div><div><span>Cobrado</span><strong>Bs {{resumen.cobrado}}</strong></div><div><span>Saldo</span><strong>Bs {{resumen.saldo}}</strong></div><div><span>Pago</span><strong>{{resumen.estado_pago}}</strong></div></div>
<div v-if="resumen.venta.estado==='CONFIRMADA' && Number(resumen.saldo)>0"><h3>Registrar cobro</h3><div class="fila"><label>Importe (Bs)<input type="number" step="0.01" min="0.01" :max="resumen.saldo" v-model="monto"></label><label>Método<select v-model="metodo"><option value="EFECTIVO">Efectivo</option><option value="QR">QR</option><option value="TRANSFERENCIA">Transferencia bancaria</option></select></label><label>Referencia (opcional)<input v-model="referencia" maxlength="120" placeholder="Comprobante o referencia"></label></div><label>Observación<input v-model="observacion" maxlength="500" placeholder="Opcional"></label><button class="principal" :disabled="guardando || Number(monto)<=0 || Number(monto)>Number(resumen.saldo)" @click="registrar">{{guardando?'Registrando...':'Confirmar cobro'}}</button></div>
<h3>Historial de cobros</h3><div class="tabla"><table><thead><tr><th>N.º</th><th>Fecha</th><th>Importe</th><th>Método</th><th>Referencia</th><th>Usuario</th></tr></thead><tbody><tr v-for="c in resumen.cobros" :key="c.id_cobro"><td>#{{c.id_cobro}}</td><td>{{new Date(c.fecha_cobro).toLocaleString('es-BO')}}</td><td>Bs {{c.monto}}</td><td>{{c.metodo_pago}}</td><td>{{c.referencia||'—'}}</td><td>{{c.usuario?.name}}</td></tr><tr v-if="!resumen.cobros.length"><td colspan="6">No hay cobros registrados.</td></tr></tbody></table></div></div>
<p class="nota">Esta etapa registra cobros. La apertura, cierre y conciliación de caja se incorporarán en la siguiente etapa.</p>
</section>
</template>
<script>
import api from '../../services/api';
export default {data(){return{idVenta:this.$route.query.venta||'',resumen:null,monto:'',metodo:'EFECTIVO',referencia:'',observacion:'',error:'',exito:'',cargando:false,guardando:false,claveOperacion:null}},mounted(){if(this.idVenta)this.consultar()},methods:{mensaje(e){return e.response?.data?.message||Object.values(e.response?.data?.errors||{}).flat().join(' ')||'No se pudo completar la operación.'},async consultar(){this.error='';this.exito='';this.resumen=null;if(!Number.isInteger(Number(this.idVenta))||Number(this.idVenta)<1){this.error='Ingrese un número de venta válido.';return}this.cargando=true;try{const {data}=await api.get('/api/cobros-ventas',{params:{id_venta:this.idVenta}});this.resumen=data;this.monto=data.saldo;this.claveOperacion=null}catch(e){this.error=this.mensaje(e)}finally{this.cargando=false}},async registrar(){if(!this.resumen||!confirm(`¿Confirmar cobro de Bs ${Number(this.monto).toFixed(2)}?`))return;this.error='';this.exito='';this.guardando=true;try{if(!this.claveOperacion)this.claveOperacion='COBRO-'+Date.now()+'-'+Math.random().toString(36).slice(2);await api.post('/api/cobros-ventas',{id_venta:this.resumen.venta.id_venta,monto:this.monto,metodo_pago:this.metodo,referencia:this.referencia||null,observacion:this.observacion||null,clave_operacion:this.claveOperacion});this.claveOperacion=null;await this.consultar();this.exito='Cobro registrado correctamente.';this.referencia='';this.observacion=''}catch(e){this.error=this.mensaje(e)}finally{this.guardando=false}}}}
</script>
<style scoped>
.cobros{max-width:1400px;margin:auto;padding:24px;color:#0c3025}.cobros h1{font-size:29px;margin:0}.cobros header p{color:#61786b}.panel{background:white;border:1px solid #dce8df;border-radius:15px;padding:22px;margin:18px 0;box-shadow:0 5px 22px #0c30250a}h2{font-size:19px}h3{margin-top:25px}.fila{display:flex;flex-wrap:wrap;align-items:end;gap:16px}label{display:block;font-weight:700;margin:10px 0}input,select{display:block;margin-top:7px;padding:10px;border:1px solid #cbdcd1;border-radius:8px;min-width:160px}button{background:white;border:1px solid #bed3c5;color:#124734;border-radius:8px;padding:11px 17px;font-weight:700;cursor:pointer}button.principal{background:#f47b20;color:white;border-color:#f47b20;margin-top:16px}button:disabled{opacity:.5;cursor:not-allowed}.metricas{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.metricas>div{background:#eef5ef;border-radius:10px;padding:15px;display:flex;flex-direction:column;gap:6px}.metricas span{font-size:13px;color:#557263}.metricas strong{font-size:22px}.tabla{overflow-x:auto}table{width:100%;border-collapse:collapse}th{background:#0c3025;color:white;text-align:left}td,th{padding:11px;border-bottom:1px solid #e2ebe5}.alerta,.exito{padding:12px;border-radius:8px}.alerta{background:#ffeded;color:#a22}.exito{background:#e9f6ee;color:#175b3b}.nota{font-size:13px;color:#637c6e}
</style>
